#include <stdio.h>

#define MAXN 100005

long long bit[MAXN];
int a[MAXN];
int n, q;

void update(int idx, long long val) {
    while (idx <= n) {
        bit[idx] += val;
        idx += idx & -idx;
    }
}

long long query(int idx) {
    long long sum = 0;
    while (idx > 0) {
        sum += bit[idx];
        idx -= idx & -idx;
    }
    return sum;
}

int main(void) {
    scanf("%d %d", &n, &q);

    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        update(i, a[i]);
    }

    for (int i = 0; i < q; i++) {
        int type;
        scanf("%d", &type);

        if (type == 0) {
            int k, p;
            scanf("%d %d", &k, &p);
            update(k, p - a[k]);
            a[k] = p;
        } else {
            int k;
            scanf("%d", &k);
            printf("%lld\n", query(k));
        }
    }

    return 0;
}
